@@ -688,4 +688,205 @@ mod tests {

         assert!(skipped.is_empty());
     }
+
+    // --- Circular reference tests ---
+
+    #[test]
+    fn topo_sort_detects_self_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn topo_sort_detects_three_node_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn topo_sort_cycle_error_mentions_involved_steps() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let err = graph.topological_order().unwrap_err();
+        let msg = err.to_string();
+        assert!(msg.contains("a"));
+        assert!(msg.contains("b"));
+    }
+
+    #[test]
+    fn topo_sort_cycle_in_subgraph_with_acyclic_nodes() {
+        let graph = DependencyGraph::builder()
+            .add_step("ok1", vec![])
+            .add_step("ok2", vec!["ok1".to_string()])
+            .add_step("cycle_a", vec!["cycle_b".to_string()])
+            .add_step("cycle_b", vec!["cycle_a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn find_cycle_empty_graph() {
+        let graph = DependencyGraph::builder().build().unwrap();
+        assert!(graph.find_cycle().is_none());
+    }
+
+    #[test]
+    fn find_cycle_single_node_no_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        assert!(graph.find_cycle().is_none());
+    }
+
+    #[test]
+    fn find_cycle_self_referencing_returns_path() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let cycle = graph.find_cycle().unwrap();
+        assert_eq!(cycle.first(), cycle.last());
+        assert!(cycle.contains(&"a".to_string()));
+    }
+
+    #[test]
+    fn find_cycle_ignores_acyclic_portion() {
+        let graph = DependencyGraph::builder()
+            .add_step("root", vec![])
+            .add_step("mid", vec!["root".to_string()])
+            .add_step("x", vec!["y".to_string()])
+            .add_step("y", vec!["x".to_string()])
+            .build()
+            .unwrap();
+
+        let cycle = graph.find_cycle().unwrap();
+        // Cycle must include x and y, not root or mid
+        assert!(cycle.contains(&"x".to_string()) || cycle.contains(&"y".to_string()));
+        assert!(!cycle.contains(&"root".to_string()));
+        assert!(!cycle.contains(&"mid".to_string()));
+    }
+
+    #[test]
+    fn parallel_groups_rejects_self_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        assert!(graph.parallel_groups().is_err());
+    }
+
+    #[test]
+    fn parallel_groups_rejects_two_node_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        assert!(graph.parallel_groups().is_err());
+    }
+
+    #[test]
+    fn parallel_groups_rejects_cycle_among_valid_steps() {
+        let graph = DependencyGraph::builder()
+            .add_step("ok", vec![])
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        assert!(graph.parallel_groups().is_err());
+    }
+
+    #[test]
+    fn transitive_dependents_terminates_on_cycle() {
+        // Build a graph where dependents form a cycle: a→b→c→a
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        // Must terminate, not infinite loop. All nodes are transitive dependents.
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        assert!(deps.contains("c"));
+    }
+
+    #[test]
+    fn transitive_dependents_terminates_on_self_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        // Must terminate. "a" depends on itself, so "a" is its own dependent.
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("a"));
+    }
+
+    #[test]
+    fn compute_skips_terminates_on_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let mut skip = HashSet::new();
+        skip.insert("a".to_string());
+
+        // Must terminate, not infinite loop
+        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
+        assert!(skipped.contains("a"));
+        assert!(skipped.contains("b"));
+    }
+
+    #[test]
+    fn is_ready_false_for_self_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        // "a" depends on itself, so it can never be ready
+        assert!(!graph.is_ready("a", &HashSet::new()));
+    }
+
+    #[test]
+    fn is_ready_false_for_mutual_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        // Neither can be ready without the other completing first
+        assert!(!graph.is_ready("a", &HashSet::new()));
+        assert!(!graph.is_ready("b", &HashSet::new()));
+    }
 }

